const text = ($input.first().json.message?.text || '').trim();
const parts = text.split(/\s+/).slice(1);
const monthArg = (parts[0] || '').toLowerCase();
const yearArg = parts[1] ? parseInt(parts[1], 10) : new Date().getFullYear();
const months = { januar:1,februar:2,maerz:3,'märz':3,april:4,mai:5,juni:6,juli:7,august:8,september:9,oktober:10,november:11,dezember:12 };
let month = months[monthArg];
if (!month && /^\d{1,2}$/.test(monthArg)) month = parseInt(monthArg, 10);
if (!month || month < 1 || month > 12) {
  return [{ json: { error: 'Bitte Monat angeben, z. B. /auslastung Mai oder /auslastung 5 2025' } }];
}
const pad = (n) => String(n).padStart(2, '0');
const from = `${yearArg}-${pad(month)}-01`;
const lastDay = new Date(yearArg, month, 0).getDate();
const to = `${yearArg}-${pad(month)}-${pad(lastDay)}`;
const chatId = $input.first().json.message.chat.id;
return [{ json: { chatId, month, year: yearArg, from, to, days: lastDay } }];

const args = $('Parse Args').first().json;
const props = ($('Lodgify – Properties').first().json.items || $('Lodgify – Properties').first().json || []);
const bookings = ($input.first().json.items || $input.first().json || []);

const totalRoomNights = props.length * args.days;
const rangeStart = new Date(args.from + 'T00:00:00Z');
const rangeEnd = new Date(args.to + 'T23:59:59Z');
const MS = 24 * 60 * 60 * 1000;

const nightsByProperty = new Map();
let bookedNights = 0;
for (const b of bookings) {
  const a = new Date((b.arrival || b.checkin || '').slice(0, 10));
  const d = new Date((b.departure || b.checkout || '').slice(0, 10));
  if (isNaN(a) || isNaN(d)) continue;
  const start = a > rangeStart ? a : rangeStart;
  const end = d < rangeEnd ? d : rangeEnd;
  const nights = Math.max(0, Math.round((end - start) / MS));
  bookedNights += nights;
  const pid = b.property_id || b.property?.id || 'unknown';
  nightsByProperty.set(pid, (nightsByProperty.get(pid) || 0) + nights);
}

const occupancy = totalRoomNights ? bookedNights / totalRoomNights : 0;
const byProperty = props.map(p => {
  const nights = nightsByProperty.get(p.id) || 0;
  return { id: p.id, name: p.name, occupancy: args.days ? nights / args.days : 0, nights };
}).sort((a, b) => b.occupancy - a.occupancy);

return [{
  json: {
    chatId: args.chatId,
    month: args.month,
    year: args.year,
    days: args.days,
    properties: props.length,
    bookedNights,
    totalRoomNights,
    occupancyPct: Math.round(occupancy * 100),
    top: byProperty.slice(0, 3),
    bottom: byProperty.slice(-3).reverse()
  }
}];
